#include <iostream>


#include <iomanip>


using namespace std;


bool prime(int n){if(n<2)return false;for(int i=2;i*i<=n;i++)if(n%i==0)return false;return true;}


int main(){int m,n;cin>>m>>n;long long sum=0;int count=0;


for(int x=m;x<=n;x++)if(prime(x)){sum+=x;count++;}


long long tenths=count?(20*sum+count)/(2*count):0;cout<<tenths/10<<'.'<<tenths%10<<'\n';}
